"use strict";(globalThis.webpackChunkapp_versions_docs=globalThis.webpackChunkapp_versions_docs||[]).push([[8297],{5582(e){e.exports=JSON.parse('{"features":[{"slug":"api-contract","title":"API contract","summary":"How Versioniq\'s JSON API meets the NL API Design Rules that apply to every endpoint, whatever it does: each response says which version answered it, errors come back as RFC 9457 problem details, and the OpenAPI document that describes the API is published by the API itself. The document lives at `openapi.json` in the repository root. `composer openapi` generates it from the controllers with nextcloud/openapi-extractor and completes it with `bin/openapi-design-rules.php`. It is linted with the Spectral ruleset of the API Design Rules (`https://static.developer.overheid.nl/adr/ruleset.yaml`).","docsUrl":"openspec/specs/api-contract/spec.md"}],"title":"Features","intro":null}')}}]);